item.content:encoded:
.orv_form p {
	margin-bottom: 0px;
}
.orv_form_steps {
	grid-row-gap: 0;
}
.orv_form .error {
	color: red;
}
.orv_form_info-protect_wrapper {
    margin: 48px 0;
}
@media(min-width: 768){ 
.estimatedWithButton {
    align-items: center;
    justify-content: center;
}
.estimatedWithButton p.estimatedBudjet {
    margin: 0 !important;
}
.e-con.e-flex>.e-con-inner {
    max-width: 100%;
}
}
@media(min-width: 530px){
.estimatedWithButton button.btnPartnerRedirect {
    margin: 0 !important;
}
}

.estimatedWithButton {
    align-items: center;
}
@media (min-width: 768px) {
.elementor-element.elementor-element-b01916b, .elementor-element.elementor-element-fe87d86, .elementor-element.elementor-element-001dd40, .elementor-element.elementor-element-7c633d6, .elementor-element.elementor-element-5dd6f60 {
    --content-width: 1296px !important;
}
	form#orv_form, .orv_form_regi_wrapper.orv-form-group {
    max-width: 760px;
    margin: 0 auto; 
		width: 100%;
}
	.orv_form_partners .partnerRow {
	padding: 5px 20px !important;
}
	.orv_form_partners .estimatedWithButton button.btnPartnerRedirect {
	padding: 12px 16px !important;
	height: auto;
	font-size: 14px !important;
}
	.orv_form_step_car-model_left p.orv_form_step_car-model-text {
	font-size: 16px !important;
}
}

.elementor-1187 .elementor-element.elementor-element-2aa3dd9 .jet-select__control {
    border: 1px solid #398453;
    border-radius: 25px;
    background: #398453;
    color: white;
}

.elementor-1187 .elementor-element.elementor-element-2aa3dd9 .jet-select__control:hover {
    border: 1px solid #398453;
    background: white;
    color: #398453;
		-webkit-appearance: yes !important;
}
.elementor-1187 .elementor-element.elementor-element-2aa3dd9 .jet-select__control:active {
    border: 1px solid #398453;
    background: white;
    color: #398453;
}

