:"497","not_found_message":"No data was found","posts_query":[],"terms_meta_query":[],"users_meta_query":[],"carousel_enabled":"yes","columns_tablet":"2","columns_mobile":"1","horizontal_gap":{"unit":"rem","size":2,"sizes":[]},"dots":"true","autoplay":"","vertical_gap":{"unit":"rem","size":0,"sizes":[]},"vertical_gap_mobile":{"unit":"rem","size":2,"sizes":[]},"arrows_box_size":{"unit":"px","size":48,"sizes":[]},"arrows_box_size_mobile":{"unit":"px","size":40,"sizes":[]},"arrows_size":{"unit":"px","size":24,"sizes":[]},"arrows_size_mobile":{"unit":"px","size":18,"sizes":[]},"arrow_color":"#FFFFFF","arrow_bg_color":"#213A7600","prev_left_position":{"unit":"px","size":-90,"sizes":[]},"next_right_position":{"unit":"px","size":-90,"sizes":[]},"dots_size":{"unit":"px","size":8,"sizes":[]},"dots_gap":{"unit":"px","size":8,"sizes":[]},"dots_bg_color":"#213A7633","dots_bg_color_hover":"#213A76","dots_bg_color_active":"#213A76","custom_css":"/* Default styling for slick dots in testimonial slider */
.testimonial-slider .jet-listing-grid__slider .jet-slick-dots li {
    border-radius: 999;
}

/* Styling for slider icons in testimonial slider */
.testimonial-slider .jet-listing-grid__slider-icon {
    border: 1px solid var(--e-global-color-primary);
    border-radius: 9999px;
}

/* Styling for slick dots container in testimonial slider */
.testimonial-slider .jet-slick-dots {
    margin: 20px 0px;
   
   
    
}

/* Media queries for responsiveness */
@media (max-width: 1530px) {
    .testimonial-slider .jet-listing-grid__slider-icon.prev-arrow {
        left: -50px !important;
    }

    .testimonial-slider .jet-listing-grid__slider-icon.next-arrow {
        right: -50px !important;
    }
}

@media (max-width: 1420px) {
    .testimonial-slider .jet-listing-grid__slider-icon.prev-arrow {
        left: 0 !important;
    }

    .testimonial-slider .jet-listing-grid__slider-icon.next-arrow {
        right: 0px !important;
    }
}

@media (max-width: 1350px) {
    .testimonial-slider .jet-slick-dots {
        -webkit-box-pack: start;
        -ms-flex-pack: start;
        justify-content: start;
        padding: 0 16px;
    }

    .testimonial-slider .jet-listing-grid__slider-icon.prev-arrow,
    .testimonial-slider .jet-listing-grid__slider-icon.next-arrow {
        left: auto !important;
        right: 90px !important;
        bottom: -15px !important;
        top: auto;
    }

    .testimonial-slider .jet-listing-grid__slider-icon.next-arrow {
        right: 16px !important;
    }

    .testimonial-slider .jet-slick-dots {
        margin: 40px 0;
        
    }
}

@media (max-width: 1024px) {
    .testimonial-slider .jet-listing-grid__slider-icon.prev-arrow,
    .testimonial-slider .jet-listing-grid__slider-icon.next-arrow {
        left: auto !important;
        right: 80px !important;
    }

    .testimonial-slider .jet-listing-grid__slider-icon.next-arrow {
        right: 15px !important;
    }
}

@media (max-width: 767px) {
    .testimonial-slider .jet-listing-grid__slider-icon.prev-arrow,
    .testimonial-slider .jet-listing-grid__slider-icon.next-arrow {
        left: auto !important;
        right: 75px !important;
    }

    .testimonial-slider .jet-listing-grid__slider-icon.next-arrow {
        right:15px !important;
    }
}
