ablet":"center","jet_parallax_layout_list":[],"_title":"Share","content_width":"full","width":{"unit":"%","size":63,"sizes":[]},"width_tablet":{"unit":"%","size":80,"sizes":[]},"width_mobile":{"unit":"%","size":80,"sizes":[]},"background_background":"classic","border_radius":{"unit":"px","top":"12","right":"12","bottom":"12","left":"12","isLinked":true},"padding":{"unit":"rem","top":"1.5","right":"1.5","bottom":"1.5","left":"1.5","isLinked":true},"padding_tablet":{"unit":"rem","top":"","right":"","bottom":"","left":"","isLinked":true},"padding_mobile":{"unit":"rem","top":"","right":"","bottom":"","left":"","isLinked":true},"__globals__":{"background_color":"globals/colors?id=f8be469"},"margin":{"unit":"rem","top":"1","right":"0","bottom":"0","left":"0","isLinked":false},"margin_tablet":{"unit":"rem","top":"","right":"","bottom":"","left":"","isLinked":true},"margin_mobile":{"unit":"rem","top":"","right":"","bottom":"","left":"","isLinked":true}},"elements":[{"id":"f9a2830","elType":"widget","settings":{"title":"Share","__globals__":{"typography_typography":"globals/typography?id=33d2c84","title_color":"globals/colors?id=8920783"}},"elements":[],"widgetType":"heading"},{"id":"717a822","elType":"widget","settings":{"share_buttons":[{"_id":"8ecfda1"},{"button":"twitter","_id":"bd785ff"},{"button":"linkedin","_id":"c2b5721"},{"button":"pinterest","_id":"bd36378"}],"view":"icon","skin":"minimal","shape":"circle","button_size":{"unit":"px","size":0.8,"sizes":[]},"icon_size":{"unit":"px","size":15,"sizes":[]},"icon_size_tablet":{"unit":"px","size":"","sizes":[]},"icon_size_mobile":{"unit":"px","size":"","sizes":[]},"color_source":"custom","__globals__":{"primary_color":"globals/colors?id=8920783","secondary_color":"globals/colors?id=f8be469"}},"elements":[],"widgetType":"share-buttons"}],"isInner":true}],"isInner":true}],"isInner":true},{"id":"2a351c6","elType":"container","settings":{"flex_direction":"column","content_width":"full","width":{"unit":"%","size":65},"jet_parallax_layout_list":[],"_title":"right","width_tablet":{"unit":"%","size":47},"width_mobile":{"unit":"%","size":"","sizes":[]},"_flex_size":"none","_element_width_tablet":"initial"},"elements":[{"id":"92095f8","elType":"container","settings":{"jet_parallax_layout_list":[],"_title":"swiss health","_element_id":"swiss","boxed_width_tablet":{"unit":"%","size":"","sizes":[]},"boxed_width_mobile":{"unit":"%","size":"","sizes":[]}},"elements":[{"id":"e7846cb","elType":"widget","settings":{"editor":"<h5>Assurance Protection Juridique en Suisse</h5><p><span style="font-weight: 400;">L'assurance protection juridique en Suisse est une forme d'assurance qui offre une couverture pour les frais juridiques et les conseils en cas de litiges. Elle vise à protéger vos droits et à vous fournir une assistance en cas de problèmes juridiques dans divers domaines de la vie quotidienne.</span></p>","_css_classes":"click-text"},"elements":[],"widgetType":"text-editor"},{"id":"c95deb7","elType":"widget","settings":{"image":{"url":"https://le-comparateur-optimis.ch/wp-content/uploads/2024/05/legale.jpg","id":2883,"size":"","alt":"","source":"library"},"width":{"unit":"%","size":1000,"sizes":[]}},"elements":[],"widgetType":"image"}],"isInner":true},{"id":"8c9a62e","elType":"container","settings":{"jet_parallax_layout_list":[],"_title":"how much","_element_id":"how-much"},"elements":[{"id":"f34fcc9","elType":"widget","settings":{"editor":"<h5>Fonctionnement de l'assurance protection juridique</h5><p><span style="font-weight: 400;">Une fois que vous avez souscrit une assurance protection juridique, vous serez couvert en cas de litiges liés à votre vie privée, votre travail, votre logement, votre consommation, ou encore vos déplacements. La couverture peut varier en fonction de la compagnie d'assurance et de la police que vous choisissez.</span></p><p><span style="font-weight: 400;">Il est important de noter que l'assurance protection juridique ne couvre généralement pas les litiges concernant des délits intentionnels, les amendes pénales ou les affaires déjà en cours avant la souscription de la police. Pour ces situations spécifiques, une évaluation individuelle peut être nécessaire.</span></p>","_css_classes":"click-text"},"elements":[],"widgetType":"text-editor"}],"isInner":true},{"id":"1a166b9","elType":"container","settings":{"jet_parallax_layout_list":[],"_element_id":"Swiss-health","_title":"Swiss health"},"elements":[{"id":"ef145f2","elType":"widget","settings":{"editor":"<h5>Comparea vous aide à y voir plus clair</h5><p><span style="font-weight: 400;">En cas de litige, vous devrez généralement contacter votre compagnie d'assurance dès que possible. Vous devrez fournir des informations détaillées sur le problème juridique rencontré et, si possible, des documents pertinents pour appuyer votre réclamation. Votre compagnie d'assurance évaluera ensuite la situation et vous fournira les conseils nécessaires ou désignera un avocat pour défendre vos intérêts.</span></p><p><span style="font-weight: 400;">Il est recommandé de lire attentivement les conditions générales de votre police d'assurance protection juridique pour comprendre les limites et exclusions de couverture. Vous pouvez également consulter des comparateurs d'assurance pour trouver la police qui correspond le mieux à vos besoins.</span></p>","_css_classes":"click-text"},"elements":[],"widgetType":"text-editor"}],"isInner":true},{"id":"6b1dfd5","elType":"container","settings":{"jet_parallax_layout_list":[],"_element_id":"supplementary","_title":"supplementary"},"elements":[{"id":"c1d37c4","elType":"widget","settings":{"editor":"<h5>Les avantages de l'assurance protection juridique</h5><p><span style="font-weight: 400;">Souscrire une assurance protection juridique vous offre plusieurs avantages, tels que :</span></p><ul><li style="font-weight: 400;" aria-level="1"><b>Accès à des conseils juridiques professionnels</b><span style="font-weight: 400;"> : Recevez des conseils de juristes qualifiés pour mieux comprendre vos droits et obligations.</span></li><li style="font-weight: 400;" aria-level="1"><b>Couverture des frais de justice</b><span style="font-weight: 400;"> : Bénéficiez d'une prise en charge des frais liés à votre défense en cas de litige.</span></li><li style="font-weight: 400;" aria-level="1"><b>Tranquillité d'esprit</b><span style="font-weight: 400;"> : Soyez assuré que vous serez soutenu et défendu en cas de problème juridique.</span></li></ul><p><span style="font-weight: 400;">Pour choisir la meilleure assurance protection juridique, il est essentiel de comparer les différentes offres disponibles sur le marché. Utilisez notre comparateur d'assurances pour trouver la police la mieux adaptée à vos besoins et bénéficiez d'une couverture complète pour protéger vos droits au quotidien.</span></p>","_css_classes":"click-text"},"elements":[],"widgetType":"text-editor"}],"isInner":true},{"id":"3046cab","elType":"container","settings":{"flex_direction":"row","flex_justify_content":"space-between","background_background":"classic","border_radius":{"unit":"rem","top":"1.25","right":"1.25","bottom":"1.25","left":"1.25","isLinked":true},"border_radius_tablet":{"unit":"rem","top":"","right":"","bottom":"","left":"","isLinked":true},"border_radius_mobile":{"unit":"rem","top":"","right":"","bottom":"","left":"","isLinked":true},"margin":{"unit":"rem","top":"01","right":"0","bottom":"0","left":"0","isLinked":false},"margin_tablet":{"unit":"rem","top":"","right":"","bottom":"","left":"","isLinked":true},"margin_mobile":{"unit":"rem","top":"","right":"","bottom":"","left":"","isLinked":true},"padding":{"unit":"rem","top":"1.5","right":"1.5","bottom":"1.5","left":"1.5","isLinked":false},"padding_tablet":{"unit":"rem","top":"","right":"","bottom":"","left":"","isLinked":true},"padding_mobile":{"unit":"rem","top":"","right":"","bottom":"","left":"","isLinked":true},"jet_parallax_layout_list":[],"_title":"author details","__globals__":{"background_color":"globals/colo